@startuml

enum Unit {
  CELSIUS
  WATT
}

class SensorController {
}

class Apartment {
  + address : string
  + emailAddress : string
}

class Inhabitant {
  + username : string
  + password : string
  + isAdmin() : boolean
}

class Room {
  + description : string
}

class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
}

class TemperatureSensor extends Sensor {
  + min : float
  + max : float
}

class PowerSensor extends Sensor {
  + counterReading : float
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

class Threshold {
  + value : float
}

class EMonitor {
}

SensorController "1" -- "*" Apartment : manages
SensorController "1" -- "*" Inhabitant : manages
Apartment "1" -- "2..*" Room : consists of
Room "1" -- "1..*" Sensor : contains
Sensor "1" -- "*" MeasuredValue : records
Sensor "1" -- "0..1" Threshold : has
Inhabitant "0..*" -- "*" Sensor : configures
SensorController "1" -- "*" EMonitor : interacts with
EMonitor "1" -- "*" Threshold : checks

@enduml

